const http = (options) => this.helpers.httpRequest(options);

async function serviceToken() {
  const body = `grant_type=client_credentials&client_id=salon-agent&client_secret=${encodeURIComponent($env.SALON_AGENT_SECRET)}`;
  const { access_token } = await http({
    method: 'POST',
    url: $env.KEYCLOAK_TOKEN_URL,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
    json: true,
  });
  return access_token;
}

async function graphql(url, token, query, variables = {}) {
  const response = await http({
    method: 'POST',
    url,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: { query, variables },
    json: true,
  });
  if (response.errors?.length) throw new Error(response.errors[0].message);
  return response.data;
}

// Se envía solo con WhatsApp configurado, con teléfono y con la autorización del cliente
function whatsappItem(phone, text, template, parameters = []) {
  const to = String(phone ?? '').replace(/\D/g, '');
  if (!$env.WHATSAPP_TOKEN || !to) return [];
  // Meta solo admite texto libre dentro de una conversación abierta: lo demás requiere una plantilla aprobada
  const message = template
    ? { type: 'template', template: { name: template, language: { code: 'es' }, components: [{ type: 'body', parameters: parameters.map((value) => ({ type: 'text', text: String(value) })) }] } }
    : { type: 'text', text: { body: text } };
  return [{ json: { payload: { messaging_product: 'whatsapp', to, ...message } } }];
}

async function clientContact(token, clientId) {
  const { getClientById } = await graphql($env.CRM_GRAPHQL_URL, token, 'query ($id: ID!) { getClientById(id: $id) { fullName phone whatsappOptIn } }', { id: clientId });
  return getClientById;
}

// La ejecución manual exige la clave de automatización
const manual = $input.first().json.headers;
if (manual && manual['x-automation-key'] !== $env.N8N_AUTOMATION_KEY) throw new Error('Clave de automatización incorrecta.');
const now = DateTime.now().setZone($env.GENERIC_TIMEZONE);
const format = (value) => value.toFormat("yyyy-MM-dd'T'HH:mm:ss");
const from = now.plus({ hours: 23 });
const to = now.plus({ hours: 24 });
const token = await serviceToken();
const { getPanelAgenda } = await graphql(
  $env.GESTION_GRAPHQL_URL,
  token,
  'query ($from: String!, $to: String!) { getPanelAgenda(from: $from, to: $to) { id clientId stylistName serviceName appointmentDate status } }',
  { from: from.toFormat('yyyy-MM-dd'), to: to.toFormat('yyyy-MM-dd') },
);
const due = getPanelAgenda.filter(({ status, appointmentDate }) => {
  const date = DateTime.fromISO(appointmentDate, { zone: $env.GENERIC_TIMEZONE });
  return status === 'CONFIRMED' && date >= from && date < to;
});

const items = [];
for (const appointment of due) {
  const date = DateTime.fromISO(appointment.appointmentDate, { zone: $env.GENERIC_TIMEZONE });
  const when = date.setLocale('es').toFormat("cccc d 'de' LLLL 'a las' HH:mm");
  const text = `Recordatorio: tu cita de ${appointment.serviceName} con ${appointment.stylistName} es el ${when}.`;
  // La referencia única evita repetir el recordatorio: el flujo corre varias veces dentro de la misma hora
  const { recordAutomationNotice: isNew } = await graphql(
    $env.CRM_GRAPHQL_URL,
    token,
    'mutation ($recipient: String!, $title: String!, $message: String!, $sourceRef: String!) { recordAutomationNotice(recipient: $recipient, title: $title, message: $message, sourceRef: $sourceRef) }',
    { recipient: appointment.clientId, title: 'Recordatorio de cita', message: text, sourceRef: `reminder:${appointment.id}` },
  );
  if (!isNew) continue;
  const contact = await clientContact(token, appointment.clientId);
  if (contact?.whatsappOptIn) {
    items.push(...whatsappItem(
      contact.phone,
      `${text} Responde 1 para confirmar o 2 para reprogramar.`,
      $env.WHATSAPP_TEMPLATE_RECORDATORIO,
      [appointment.serviceName, appointment.stylistName, when],
    ));
  }
}
return items;
